<template>
  <section class="traffic-analysis" :aria-busy="loading">
    <header class="analysis-header">
      <div><span class="eyebrow">经营 / 广告效果</span><h1>广告流量分析</h1><p>按中转站、来源页面和展示位置，查看广告效果。</p></div>
      <span class="connection" :class="{failed:error}"><i />{{ loading ? '更新中' : error ? '连接异常' : '数据已同步' }}<small>北京时间</small></span>
    </header>

    <section class="filter-panel">
      <div class="filters">
        <div class="filter-field"><span id="traffic-ad-label">广告中转站</span><a-select v-model="selectedAd" aria-labelledby="traffic-ad-label" placeholder="全部广告中转站" allow-clear allow-search style="width:240px"><a-option v-for="ad in ads" :key="ad.id" :value="String(ad.id)">{{ ad.name }}</a-option></a-select></div>
        <div class="filter-field"><span id="traffic-date-label">日期范围</span><a-range-picker v-model="dates" aria-labelledby="traffic-date-label" :allow-clear="false" style="width:260px" /></div>
        <div class="range-shortcuts"><button v-for="days in [7,30]" :key="days" :class="{chosen:matchesRange(days)}" @click="setRange(days)">近 {{ days }} 天</button></div>
        <div class="filter-field"><span id="traffic-surface-label">展示类型</span><a-select v-model="surface" aria-labelledby="traffic-surface-label" style="width:165px"><a-option value="">广告 + 站内收录</a-option><a-option value="banner">仅广告位</a-option><a-option value="directory">仅站内收录入口</a-option></a-select></div>
        <a-button class="refresh" size="large" :loading="loading" @click="load"><IconRefresh />刷新数据</a-button>
      </div>
      <div class="audience-filter">
        <div class="segmented" aria-label="流量统计口径"><button v-for="item in modes" :key="item.key" :class="{selected:mode===item.key}" :aria-pressed="mode===item.key" @click="mode=item.key">{{ item.label }}</button></div>
        <span>{{ mode === 'human' ? '排除已识别 AI、爬虫与自动化访问' : mode === 'ai' ? '仅展示命中 AI 访问规则的事件' : '包含 AI、爬虫及历史未分类事件' }}</span>
      </div>
    </section>
    <div class="object-context"><IconLink /><b>{{ selectedAdName }}</b><span>统计投放期内的广告位与同域名站点入口，不包含未投广告的中转站。</span></div>
    <a-alert v-if="adsError" type="warning" class="feedback">广告名单加载失败：{{ adsError }}<a-button type="text" @click="loadAds">重新加载名单</a-button></a-alert>

    <a-alert v-if="error" type="error" class="feedback">{{ error }}<a-button type="text" @click="load">重试</a-button></a-alert>
    <div v-else-if="report.unknown?.impressions || report.unknown?.clicks" class="history-note" role="note"><IconInfoCircle class="note-icon" /><span><b>历史数据待归因</b> 有 {{ number(report.unknown.impressions) }} 次曝光、{{ number(report.unknown.clicks) }} 次点击未记录完整来源或识别信息。{{ mode === 'human' ? '未计入过滤后流量，切换「全部流量」可查看原计数。' : '来源未记录，无法分配到首页、站点或投票页。' }}</span></div>

    <div class="metric-strip">
      <article v-for="(metric,index) in metrics" :key="metric.label"><span>{{ metric.label }}<component :is="metricIcons[index]" /></span><strong :class="metric.tone">{{ metric.value }}<em v-if="index!==2">次</em></strong><small>{{ metric.note }}</small></article>
    </div>

    <section class="locations-panel panel">
      <header class="section-heading"><div><h2>流量来自哪里<span class="heading-tag">按页面归因</span></h2><p>首页、站点、投票分开统计；点击页面卡片，下方查看具体位置。</p></div><span class="scope-label">{{ modeLabel }}</span></header>
      <div class="page-tiles" aria-label="按来源页面筛选">
        <button v-for="item in primaryPages" :key="item.page" :class="{active:page===item.page}" :aria-pressed="page===item.page" @click="page=page===item.page?'':item.page">
          <span class="page-tile-top"><i><component :is="pageIcons[item.page]" /></i>{{ item.page_label }}<b>{{ page===item.page ? '当前页面' : '查看明细' }}<IconArrowRight /></b></span>
          <span class="page-counts"><strong>{{ number(item.impressions) }}</strong><small>曝光</small><em /> <strong>{{ number(item.clicks) }}</strong><small>点击</small></span>
          <span class="page-tile-footer"><span>{{ pageDescriptions[item.page] }}</span><b>CTR {{ percent(item.ctr) }}</b></span>
        </button>
      </div>
      <div class="other-pages" aria-label="其他来源页面"><button :class="{active:!page}" :aria-pressed="!page" @click="page=''">全部页面</button><button v-for="item in secondaryPages" :key="item.page" :class="{active:page===item.page}" :aria-pressed="page===item.page" @click="page=item.page">{{ item.page_label }}<span>{{ number(item.clicks) }} 点击</span></button></div>
      <div class="detail-heading"><span><b>{{ selectedPageName }}</b> · {{ report.locations?.length || 0 }} 个有记录的位置</span><button v-if="page" @click="page=''">查看全部页面 ×</button></div>
      <a-table :key="page+surface+selectedAd+mode" :columns="locationColumns" :data="report.locations || []" :loading="loading" :pagination="{pageSize:8,hideOnSinglePage:true}" :scroll="{x:1060}" :bordered="false" row-key="key">
        <template #page="{record}"><span class="page-name">{{ record.page_label }}</span></template>
        <template #region="{record}"><b class="region-name">{{ record.region }}</b><small class="location-type">{{ record.surface==='banner'?'广告位':'站内收录入口' }}</small><small class="location-path" :title="record.paths?.join('、')">{{ record.paths?.join('、') }}</small></template>
        <template #impressions="{record}"><span class="number-cell">{{ number(record.impressions) }}</span></template>
        <template #clicks="{record}"><span class="number-cell accent">{{ number(record.clicks) }}</span></template>
        <template #details="{record}">{{ record.page==='unknown' ? '—' : number(record.detail_clicks) }}</template>
        <template #outbound="{record}">{{ record.page==='unknown' ? '—' : number(record.outbound_clicks) }}</template>
        <template #unclassified="{record}">{{ number(record.unclassified_clicks) }}</template>
        <template #ctr="{record}">{{ percent(record.ctr) }}</template>
        <template #empty><div class="table-empty">{{ error ? '统计暂时无法读取' : loading ? '正在读取统计' : '这个范围还没有位置记录' }}<small v-if="!error">新曝光和点击将在上报后显示；旧数据不会补造来源。</small></div></template>
      </a-table>
    </section>

    <div class="lower-grid" :class="{'daily-expanded':dailyOpen}">
      <section class="panel trend-panel">
        <header class="section-heading"><div><h2>每日趋势</h2><p>{{ selectedPageName }} · {{ modeLabel }} · {{ report.start }} 至 {{ report.end }}</p></div><div class="small-segmented" aria-label="趋势指标"><button :class="{selected:chartMetric==='impressions'}" @click="chartMetric='impressions'">曝光</button><button :class="{selected:chartMetric==='clicks'}" @click="chartMetric='clicks'">点击</button></div></header>
        <div v-if="loading || error || !hasTrend" class="trend-empty"><span class="empty-chart-icon"><IconBarChart /></span><strong>{{ error ? '趋势数据未加载' : loading ? '正在读取趋势' : '暂无'+(chartMetric==='impressions'?'曝光':'点击')+'记录' }}</strong><small>{{ error ? '连接恢复后请刷新重试' : mode==='human' && report.unknown?.impressions ? '当前仅有历史未分类数据，可切换全部流量查看。' : '有新记录后，这里会显示每天的变化。' }}</small></div>
        <svg v-else class="trend-chart" viewBox="0 0 760 195" role="img" :aria-label="selectedPageName+modeLabel+'每日'+(chartMetric==='impressions'?'曝光':'点击')+'趋势'">
          <g v-for="tick in [0,1,2]" :key="tick"><line x1="52" x2="738" :y1="18+tick*65" :y2="18+tick*65" stroke="#e9edf3" /><text x="40" :y="22+tick*65" text-anchor="end">{{ Math.round(maximum*(1-tick/2)) }}</text></g>
          <defs><linearGradient id="traffic-chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#4479df" stop-opacity=".18"/><stop offset="100%" stop-color="#4479df" stop-opacity=".01"/></linearGradient></defs><path :d="area" fill="url(#traffic-chart-fill)" /><polyline :points="points" fill="none" stroke="#4479df" stroke-width="2.3" stroke-linejoin="round" />
          <circle v-for="(day,i) in report.daily" :key="day.day" :cx="x(i)" :cy="y(day[chartMetric])" :r="day[chartMetric] ? 3 : 0" fill="#4479df"><title>{{ day.day }} · {{ day[chartMetric] }} {{ chartMetric==='impressions'?'次曝光':'次点击' }}</title></circle>
          <text x="52" y="178">{{ report.start?.slice(5) }}</text><text x="738" y="178" text-anchor="end">{{ report.end?.slice(5) }}</text>
        </svg>
        <div class="panel-footer"><button class="disclosure-button" :aria-expanded="dailyOpen" aria-controls="traffic-daily-data" @click="dailyOpen=!dailyOpen"><IconCalendar />逐日明细<IconDown :class="{rotated:dailyOpen}" /></button><span>按日期从新到旧</span></div>
        <div v-if="dailyOpen" id="traffic-daily-data" class="daily-data">
          <div class="daily-toolbar"><span>{{ dailyRows.length }} 天</span><a-checkbox v-model="onlyActiveDays">仅显示有数据的日期</a-checkbox></div>
          <div class="daily-table-scroll"><table class="daily-table"><thead><tr><th>日期</th><th>曝光次数</th><th>点击次数</th><th>点击率</th></tr></thead><tbody><tr v-for="row in dailyRows" :key="row.day"><td>{{ row.day }}</td><td>{{ number(row.impressions) }}</td><td>{{ number(row.clicks) }}</td><td>{{ percent(row.ctr) }}</td></tr><tr v-if="!dailyRows.length"><td colspan="4" class="daily-empty">{{ loading ? '正在加载' : error ? '数据未加载，请重试' : '当前筛选没有逐日记录' }}</td></tr></tbody></table></div>
        </div>
      </section>
      <section class="panel audience-panel">
        <header class="section-heading"><div><h2>流量构成</h2><p>过滤前的全部事件 · 色条表示曝光占比</p></div></header>
        <div class="composition-track"><i v-for="item in audiences" :key="item.key" :style="{width:item.share+'%',background:item.color}" /></div>
        <div class="audience-table"><div class="audience-table-head"><span>访问类型</span><span>曝光</span><span>点击</span></div><div v-for="item in audiences" :key="item.key"><span><i :style="{background:item.color}" />{{ item.label }}</span><b>{{ number(item.impressions) }}</b><b>{{ number(item.clicks) }}</b></div></div>
        <div class="panel-footer"><button class="disclosure-button" :aria-expanded="rulesOpen" aria-controls="traffic-rules" @click="rulesOpen=!rulesOpen"><IconFilter />识别规则<IconDown :class="{rotated:rulesOpen}" /></button><span>不等同于真人认证</span></div><ul v-if="rulesOpen" id="traffic-rules" class="rules-list"><li v-for="row in report.audiences || []" :key="row.audience+row.reason"><code>{{ row.reason }}</code><span>{{ number(row.impressions) }} 曝光 / {{ number(row.clicks) }} 点击</span></li><li v-if="!report.audiences?.length" class="rules-empty">{{ error ? '数据未加载' : '当前范围没有规则命中记录' }}</li></ul>
      </section>
    </div>
    <section class="method-panel">
      <button class="method-toggle" :aria-expanded="methodOpen" aria-controls="traffic-method" @click="methodOpen=!methodOpen"><IconInfoCircle /><span><b>统计口径</b><small>曝光如何计算、哪些点击会计入、历史数据如何处理</small></span><IconDown :class="{rotated:methodOpen}" /></button>
      <div v-if="methodOpen" id="traffic-method" class="method-grid"><article><b>什么算一次曝光</b><p>页面在前台，内容至少 50% 可见并持续 1 秒。同一次页面访问、同一广告及位置只计一次；推荐卡片和投票记录按整条内容计算。</p></article><article><b>什么算一次点击</b><p>进入详情、跳转官网和未区分三项之和等于总点击。赞成、反对、收藏和展开不计入。点击率 = 总点击 ÷ 曝光，多次点击可能使其超过 100%。</p></article><article><b>过滤后流量</b><p>排除已识别 AI、爬虫、自动化浏览器和缺失 User-Agent 的事件。代表未识别为自动化，不能保证全部为真人。</p></article><article><b>统计范围与旧数据</b><p>仅统计广告投放期内的广告位及精确匹配同域名的站内入口。同域名多投放会分别归因，合计不是去重人数。旧数据缺失来源时单列，不补推首页或真人。</p></article></div>
    </section>
  </section>
</template>

<script setup>
import { computed, onMounted, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { api } from '../api';
import { IconHome, IconStorage, IconThumbUp, IconEye, IconThunderbolt, IconBarChart, IconFilter, IconRefresh, IconLink, IconInfoCircle, IconArrowRight, IconCalendar, IconDown } from '@arco-design/web-vue/es/icon';
const todayText=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const route=useRoute(),router=useRouter();
const selectedAd=ref(String(route.query.ad_id || '')),ads=ref([]),adsError=ref(''),dates=ref([]),mode=ref('human'),surface=ref(''),page=ref(''),loading=ref(true),error=ref(''),report=ref({}),chartMetric=ref('impressions');
const dailyOpen=ref(false),rulesOpen=ref(false),methodOpen=ref(false),onlyActiveDays=ref(false);
let request=0;
const modes=[{key:'human',label:'过滤后流量'},{key:'all',label:'全部流量'},{key:'ai',label:'已识别 AI'}];
const pageIcons={home:IconHome,stations:IconStorage,vote:IconThumbUp};
const metricIcons=[IconEye,IconThunderbolt,IconBarChart,IconFilter];
const pageDescriptions={home:'推荐站点 · 站点榜单 · 广告位',stations:'列表 / 分类 / 收藏 · 广告位',vote:'口碑榜 · 最新点评 · 广告位'};
const selectedAdName=computed(()=>selectedAd.value?ads.value.find(ad=>String(ad.id)===selectedAd.value)?.name||'所选广告 #'+selectedAd.value:'全部广告中转站');
function rangeDates(days){const end=todayText(),start=new Date(end+'T00:00:00Z');start.setUTCDate(start.getUTCDate()-days+1);return[start.toISOString().slice(0,10),end];}
function setRange(days){dates.value=rangeDates(days);}
function matchesRange(days){return dates.value.join()===rangeDates(days).join();}
setRange(30);
const number=value=>loading.value||error.value?'—':Number(value||0).toLocaleString('zh-CN');
const percent=value=>loading.value||error.value||value==null?'—':Number(value).toFixed(2)+'%';
const modeLabel=computed(()=>modes.find(item=>item.key===mode.value)?.label);
const selectedPageName=computed(()=>page.value?(report.value.pages||[]).find(item=>item.page===page.value)?.page_label||'所选页面':'全部页面');
const pages=computed(()=>report.value.pages||[{page:'home',page_label:'首页'},{page:'stations',page_label:'站点列表'},{page:'detail',page_label:'站点详情'},{page:'vote',page_label:'投票'},{page:'models',page_label:'模型'},{page:'search',page_label:'搜索'},{page:'other',page_label:'其他页面'},{page:'unknown',page_label:'历史 / 来源未知'}]);
const primaryPages=computed(()=>['home','stations','vote'].map(key=>pages.value.find(item=>item.page===key)).filter(Boolean));
const secondaryPages=computed(()=>pages.value.filter(item=>!['home','stations','vote'].includes(item.page)));
const metrics=computed(()=>[
 {label:'曝光次数',value:number(report.value.summary?.impressions),note:'所选页面与入口 · '+modeLabel.value,tone:'blue'},
 {label:'点击次数',value:number(report.value.summary?.clicks),note:'进入详情 + 跳转官网 + 未区分',tone:''},
 {label:'点击率',value:percent(report.value.summary?.ctr),note:'点击 ÷ 曝光',tone:''},
 {label:'自动化曝光',value:number(report.value.excluded?.impressions),note:'已识别 AI / 爬虫 · 点击 '+number(report.value.excluded?.clicks)+' 次',tone:'subtle'}]);
const audiences=computed(()=>{const rows=report.value.audiences||[];const definitions=[['human','过滤后流量','#4676d7'],['ai','已识别 AI','#9b83d3'],['bot','其他自动化','#e4ad59'],['unknown','历史 / 未知','#aab3c3']];const total=rows.reduce((sum,row)=>sum+row.impressions,0);return definitions.map(([key,label,color])=>{const list=rows.filter(row=>key==='unknown'?['legacy','unknown'].includes(row.audience):row.audience===key);const impressions=list.reduce((sum,row)=>sum+row.impressions,0),clicks=list.reduce((sum,row)=>sum+row.clicks,0);return{key,label,color,impressions,clicks,share:total?impressions/total*100:0};});});
const locationColumns=[{title:'来源页面',slotName:'page',width:140},{title:'具体位置',slotName:'region',width:210},{title:'曝光次数',slotName:'impressions',align:'right',width:115},{title:'总点击',slotName:'clicks',align:'right',width:100},{title:'进入详情',slotName:'details',align:'right',width:110},{title:'跳转官网',slotName:'outbound',align:'right',width:110},{title:'未区分点击',slotName:'unclassified',align:'right',width:110},{title:'点击率',slotName:'ctr',align:'right',width:105}];
const dailyRows=computed(()=>loading.value||error.value?[]:[...(report.value.daily||[])].filter(row=>!onlyActiveDays.value||row.impressions||row.clicks).reverse());
const maximum=computed(()=>Math.max(1,...(report.value.daily||[]).map(row=>row[chartMetric.value])));
const hasTrend=computed(()=>report.value.daily?.some(row=>row[chartMetric.value]));
const x=index=>52+index*686/Math.max(1,(report.value.daily?.length||1)-1);
const y=value=>148-value/maximum.value*130;
const points=computed(()=>(report.value.daily||[]).map((row,i)=>`${x(i)},${y(row[chartMetric.value])}`).join(' '));
const area=computed(()=>`M52,148 L${points.value.replace(/ /g,' L')} L738,148 Z`);
async function load(){if(dates.value?.length!==2||!dates.value.every(Boolean))return;const seq=++request;loading.value=true;error.value='';try{const query=new URLSearchParams({start:dates.value[0],end:dates.value[1],mode:mode.value,surface:surface.value,page:page.value});if(selectedAd.value)query.set('ad_id',selectedAd.value);const data=await api('/api/ads/analytics?'+query);if(seq!==request)return;data.locations=(data.locations||[]).map((row,i)=>({...row,key:`${row.page}-${row.region}-${row.surface}-${i}`}));report.value=data;}catch(err){if(seq===request){error.value=err.message;report.value={};}}finally{if(seq===request)loading.value=false;}}
async function loadAds(){adsError.value='';try{let current=1,total=1,items=[];while(items.length<total){const data=await api(`/api/ads?page=${current++}&size=100`);items.push(...data.items);total=data.total;if(!data.items.length)break;}ads.value=items;}catch(err){adsError.value=err.message;}}
watch([dates,mode,surface,page,selectedAd],load);
watch(selectedAd,value=>router.replace({query:{...route.query,ad_id:value||undefined}}));
watch(()=>route.query.ad_id,value=>{selectedAd.value=String(value||'');});
onMounted(()=>{loadAds();load();});
</script>

<style scoped>
.traffic-analysis{--ink:#202936;--text:#586576;--muted:#717d8d;--line:#e6eaf0;--accent:#3468d4;color:var(--ink);font:14px/1.6 Inter,"Segoe UI","Microsoft YaHei",sans-serif}
